(async()=>{try{if(!window.motionHistoryReady)await new Promise(r=>window.addEventListener('motion-history-ready',r,{once:true}));const api=await import('./model-studio.js?v=motion-v70'),recipes=await import('./model-recipes.js?v=motion-v70');function editor(host,l,save){l.params.scene3D??=recipes.createModelRecipe('box');const scene=()=>l.params.scene3D;const info=document.createElement('p');info.textContent='Create geometry locally. Select parts, set XYZ transforms, or use scene JSON for hierarchy, camera and animation keys.';host.append(info);const add=document.createElement('select');for(const kind of ['box','sphere','cylinder','cone','torus','plane','heightfield','lathe','extrusion','helmet','bicycle','ruin','biped']){const o=document.createElement('option');o.value=kind;o.textContent=kind;add.append(o)}host.append(add);const button=(label,fn)=>{const b=document.createElement('button');b.className='pill';b.textContent=label;b.onclick=fn;host.append(b);};button('Add part',()=>{const n=recipes.createModelRecipe(add.value||'box').nodes[0];const suffix='-'+Date.now();const rename=n=>{n.id+=suffix;for(const c of n.children||[])rename(c)};rename(n);scene().nodes.push(n);save();renderBlankInspector()});const flatten=(nodes,out=[])=>{for(const n of nodes){out.push(n);flatten(n.children||[],out)}return out};const nodes=flatten(scene().nodes),pick=document.createElement('select');for(const n of nodes){const o=document.createElement('option');o.value=n.id;o.textContent=n.name||n.id;pick.append(o)}host.append(pick);const selected=nodes.find(n=>n.id===l.params.modelSelected)||nodes[0];pick.value=selected?.id||'';pick.onchange=()=>{l.params.modelSelected=pick.value;renderBlankInspector()};if(selected){for(const [key,label,defaults]of [['position','Position',[0,0,0]],['rotation','Rotation degrees',[0,0,0]],['scale','Scale',[1,1,1]]]){selected[key]??=[...defaults];for(let i=0;i<3;i++)blankField(host,label+' '+'XYZ'[i],selected[key],String(i),'number',{step:.05});}selected.material??={color:'#999999'};blankField(host,'Part color',selected.material,'color','color');blankField(host,'Texture slot (optional)',selected.material,'textureSlot','text');selected.animation??={};selected.animation.spin??=[0,0,0];for(let i=0;i<3;i++)blankField(host,'Spin '+'XYZ'[i]+' degrees/s',selected.animation.spin,String(i),'number',{step:1});button('Duplicate part',()=>{const n=structuredClone(selected),suffix='-copy-'+Date.now();const rename=n=>{n.id+=suffix;for(const child of n.children||[])rename(child)};rename(n);scene().nodes.push(n);save();renderBlankInspector()});blankField(host,'Keyframe time (seconds)',l.params,'modelKeyTime','number',{step:.1});button('Set transform keyframe',()=>{const time=Number(l.params.modelKeyTime)||0;for(const key of ['position','rotation','scale']){selected.animation[key]??=[];selected.animation[key]=selected.animation[key].filter(k=>k.time!==time);selected.animation[key].push({time,value:[...selected[key]],ease:'smooth'});}save();renderBlankInspector()});button('Remove part',()=>{function remove(nodes){const i=nodes.indexOf(selected);if(i>=0)nodes.splice(i,1);else for(const n of nodes)remove(n.children||[])}remove(scene().nodes);save();renderBlankInspector()});}scene().camera??=structuredClone(api.modelStudioDefaults.scene3D.camera);for(const key of ['position','target'])for(let i=0;i<3;i++)blankField(host,'Camera '+key+' '+'XYZ'[i],scene().camera[key],String(i),'number',{step:.1});blankField(host,'Camera field of view',scene().camera,'fov','number',{step:1});scene().lights??={ambient:.42,intensity:.65,direction:[-.4,.8,.6]};blankField(host,'Ambient light',scene().lights,'ambient','number',{step:.05});blankField(host,'Directional light strength',scene().lights,'intensity','number',{step:.05});for(let i=0;i<3;i++)blankField(host,'Light direction '+'XYZ'[i],scene().lights.direction,String(i),'number',{step:.1});button('Set camera keyframe',()=>{const time=Number(l.params.modelKeyTime)||0;scene().camera.keys??=[];scene().camera.keys=scene().camera.keys.filter(k=>k.time!==time);scene().camera.keys.push({time,value:[...scene().camera.position],ease:'smooth'});save()});const text=document.createElement('textarea');text.value=JSON.stringify(scene(),null,2);text.setAttribute('aria-label','3D scene JSON');host.append(text);const status=document.createElement('p');host.append(status);button('Apply scene JSON',()=>{try{l.params.scene3D=api.validateModelScene(JSON.parse(text.value));save();renderBlankInspector()}catch(e){status.textContent=e.message}});if(l.params.sequenceTarget)button('Apply model to sequence',()=>{fx.expansionModelOverrides??={};fx.expansionModelOverrides[l.params.sequenceTarget]=structuredClone(scene());saveEffects();base._renderKey='';});button('Export model scene JSON',()=>downloadData(scene(),'model-scene.json'));button('Export OBJ',()=>{const blob=new Blob([api.exportModelOBJ(scene())],{type:'text/plain'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='model.obj';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)});const input=document.createElement('input');input.type='file';input.accept='.obj,.json';input.setAttribute('aria-label','Import OBJ or model scene JSON');input.onchange=async()=>{try{const file=input.files[0],s=await file.text();l.params.scene3D=file.name.toLowerCase().endsWith('.obj')?api.importModelOBJ(s):api.validateModelScene(JSON.parse(s));save();renderBlankInspector()}catch(e){status.textContent=e.message}};host.append(input);for(const el of host.querySelectorAll('input'))el.addEventListener?.('change',()=>save());}
registerCapability('modelStudio',{label:'Build a 3D scene',category:'3D creation',defaults:structuredClone(api.modelStudioDefaults),slots:['salvageFacade','salvageGround','historyShoePaper'],render(c,age,l){api.paintModelScene(c,l.params.scene3D,age,sprites)},edit:editor});const b=document.createElement('button');b.className='pill';b.textContent='Build 3D scene';b.onclick=()=>{openBlank();addBlankLayer('modelStudio');};document.querySelector('#openEditor').parentElement.append(b);window.MotionModelStudio={...api,...recipes};}catch(e){console.error('Model studio:',e)}})();
